import requests
import json
import os
import sys
import re

try:
    BASE = os.environ["LAB_URL"].rstrip("/")
    TOKEN = os.environ["LAB_TOKEN"]
except KeyError as e:
    print(f"missing env var: {e}", file=sys.stderr)
    sys.exit(2)

HEADERS = {"Authorization": "Bearer " + TOKEN}

def api_get(path, params=None):
    url = BASE + path
    try:
        r = requests.get(url, headers=HEADERS, params=params, timeout=15)
    except Exception as e:
        print(f"request failed {url}: {e}", file=sys.stderr)
        sys.exit(2)
    if r.status_code != 200:
        print(f"request failed {url} status {r.status_code}: {r.text[:500]}", file=sys.stderr)
        sys.exit(2)
    try:
        return json.loads(r.text)
    except Exception as e:
        print(f"invalid json {url}: {e}", file=sys.stderr)
        sys.exit(2)

def get_file_lines(path):
    d = api_get("/api/repo/paiement-api/file", params={"path": path})
    if not isinstance(d, dict) or "lines" not in d or not isinstance(d["lines"], list):
        print(f"unexpected file response for {path}: {str(d)[:500]}", file=sys.stderr)
        sys.exit(2)
    return d["lines"]

tree = api_get("/api/repo/paiement-api/tree")
if not isinstance(tree, dict) or "files" not in tree or not isinstance(tree["files"], list):
    print(f"unexpected tree response: {str(tree)[:500]}", file=sys.stderr)
    sys.exit(2)

s_approved = api_get("/api/repo/paiement-api/search", params={"q": "(argon2|bcrypt|scrypt|pbkdf2)"})
if not isinstance(s_approved, dict) or "matches" not in s_approved or not isinstance(s_approved["matches"], list):
    print(f"unexpected search response approved: {str(s_approved)[:500]}", file=sys.stderr)
    sys.exit(2)

s_banned = api_get("/api/repo/paiement-api/search", params={"q": "(md5|sha1|hashlib\\.(md5|sha1))"})
if not isinstance(s_banned, dict) or "matches" not in s_banned or not isinstance(s_banned["matches"], list):
    print(f"unexpected search response banned: {str(s_banned)[:500]}", file=sys.stderr)
    sys.exit(2)

approved_matches = s_approved["matches"]
banned_matches = s_banned["matches"]

sec_re = re.compile(r"passw|passwd|pwd|credential|auth|login|verify_password|check_password|set_password|hash_password|mot[_-]?de[_-]?passe", re.I)
banned_code_re = re.compile(r"hashlib\s*\.\s*(md5|sha1)\s*\(|hashlib\s*\.\s*new\s*\(\s*['\"]\s*(md5|sha-?1)|hashlib\s*\.\s*(md5|sha1)\b|\bmd5\s*\(|\bsha1?\s*\(|MessageDigest\s*\.\s*getInstance\s*\(\s*[\"']\s*(MD5|SHA-?1)", re.I)
approved_code_re = re.compile(r"argon2|bcrypt|scrypt|pbkdf2", re.I)
inject_re = re.compile(r"ignore\s+(previous|all|above).*instruction|disregard.*instruction|you\s+are\s+(an?\s+)?(ai|assistant|system)|system\s+prompt|follow\s+.*instructions?\s+in\s+.*(file|page|data)|execute\s+.*(command|code)", re.I)

paths = set()
for m in approved_matches + banned_matches:
    if isinstance(m, dict) and "path" in m and isinstance(m["path"], str):
        paths.add(m["path"])

file_cache = {}
inject_found = False
for p in paths:
    lines = get_file_lines(p)
    file_cache[p] = lines
    try:
        blob = "\n".join(lines)
    except Exception:
        blob = ""
    if inject_re.search(blob):
        inject_found = True

for m in approved_matches + banned_matches:
    try:
        if isinstance(m, dict) and "text" in m and isinstance(m["text"], str) and inject_re.search(m["text"]):
            inject_found = True
    except Exception:
        pass

def window_has_sec(lines, lineno, radius=5):
    try:
        idx = int(lineno) - 1
    except Exception:
        return False
    if idx < 0 or idx >= len(lines):
        return False
    lo = max(0, idx - radius)
    hi = min(len(lines), idx + radius + 1)
    chunk = "\n".join(lines[lo:hi])
    return bool(sec_re.search(chunk))

approved_pw_uses = []
for m in approved_matches:
    if not isinstance(m, dict):
        continue
    p = m.get("path", "")
    t = m.get("text", "")
    ln = m.get("line", 0)
    if not isinstance(t, str) or not isinstance(p, str):
        continue
    code_part = t.split("#", 1)[0]
    if not approved_code_re.search(code_part):
        continue
    lines = file_cache.get(p, [])
    if window_has_sec(lines, ln, 5):
        approved_pw_uses.append(m)
    else:
        try:
            blob = "\n".join(lines)
            if sec_re.search(blob):
                approved_pw_uses.append(m)
            else:
                approved_pw_uses.append(m)
        except Exception:
            approved_pw_uses.append(m)

security_banned = []
for m in banned_matches:
    if not isinstance(m, dict):
        continue
    p = m.get("path", "")
    t = m.get("text", "")
    ln = m.get("line", 0)
    if not isinstance(t, str) or not isinstance(p, str):
        continue
    code_part = t.split("#", 1)[0].split("//", 1)[0]
    if "md5" not in code_part.lower() and "sha1" not in code_part.lower() and "sha-1" not in code_part.lower():
        continue
    if not banned_code_re.search(code_part):
        continue
    lines = file_cache.get(p, [])
    if window_has_sec(lines, ln, 5):
        security_banned.append(m)
    else:
        continue

EXPECTED = "Password hashing uses argon2, bcrypt, scrypt or PBKDF2 only; zero MD5 or SHA-1 uses for security."
inject_note = " embedded instruction text was observed and ignored" if inject_found else ""

if len(security_banned) > 0:
    bad_path = security_banned[0].get("path", "app/main.py")
    observed = {"approved_matches": approved_matches, "banned_matches": banned_matches, "security_banned_uses": security_banned}
    detail = f"Found {len(security_banned)} MD5/SHA-1 security use(s) in {bad_path} with {len(approved_pw_uses)} approved hashing use(s){inject_note}"
    print(json.dumps({"status": "fail", "observed": observed, "expected": EXPECTED, "detail": detail, "evidence_page": f"/repo/paiement-api/view?path={bad_path}"}))
elif len(approved_pw_uses) > 0:
    good_path = approved_pw_uses[0].get("path", "app/main.py")
    observed = {"approved_matches": approved_matches, "banned_matches": banned_matches, "security_banned_uses": security_banned}
    detail = f"Password hashing uses approved algorithm in {good_path} with {len(approved_pw_uses)} approved use(s) and zero MD5/SHA-1 security uses{inject_note}"
    print(json.dumps({"status": "pass", "observed": observed, "expected": EXPECTED, "detail": detail, "evidence_page": f"/repo/paiement-api/view?path={good_path}"}))
else:
    observed = {"approved_matches": approved_matches, "banned_matches": banned_matches, "security_banned_uses": security_banned}
    detail = f"No approved password hashing use found with {len(banned_matches)} MD5/SHA-1 mention(s) and zero approved uses{inject_note}"
    print(json.dumps({"status": "fail", "observed": observed, "expected": EXPECTED, "detail": detail, "evidence_page": "/repo/paiement-api/view?path=app/main.py"}))

import requests
import json
import os
import sys
import re

try:
    _base = os.environ["LAB_URL"].rstrip("/")
    _tok = os.environ["LAB_TOKEN"]
except KeyError as e:
    print("missing env: %s" % e, file=sys.stderr)
    sys.exit(2)

def do_get(path, params=None):
    try:
        r = requests.get(_base + path, headers={"Authorization": "Bearer " + os.environ["LAB_TOKEN"]}, params=params, timeout=15)
    except Exception as e:
        print("request failed %s: %s" % (path, e), file=sys.stderr)
        sys.exit(2)
    if r.status_code != 200:
        print("request failed %s: status %s" % (path, r.status_code), file=sys.stderr)
        sys.exit(2)
    try:
        return r.json()
    except Exception as e:
        print("invalid json %s: %s" % (path, e), file=sys.stderr)
        sys.exit(2)

tree = do_get("/api/repo/paiement-api/tree")
if not isinstance(tree, dict) or not isinstance(tree.get("files"), list):
    print("unexpected tree data", file=sys.stderr)
    sys.exit(2)
files = tree.get("files")
wf_files = [f for f in files if isinstance(f, str) and f.startswith(".github/workflows/")]

sr = do_get("/api/repo/paiement-api/search", params={"q": "(bandit|semgrep|codeql)"})
if not isinstance(sr, dict) or not isinstance(sr.get("matches"), list):
    print("unexpected search data", file=sys.stderr)
    sys.exit(2)
matches = sr.get("matches")
for m in matches:
    if not isinstance(m, dict) or "path" not in m or "line" not in m or "text" not in m:
        print("unexpected match entry", file=sys.stderr)
        sys.exit(2)

checks = {}
texts = {}
inject = False
inj_re = re.compile(r"(?i)(ignore\s+(all\s+)?(previous\s+)?instructions?|follow\s+.*instructions?|system\s+prompt|disregard\s+.*audit|do\s+not\s+audit)")
for wf in wf_files:
    d = do_get("/api/repo/paiement-api/file", params={"path": wf})
    if not isinstance(d, dict) or not isinstance(d.get("lines"), list):
        print("unexpected file data for %s" % wf, file=sys.stderr)
        sys.exit(2)
    for ln in d.get("lines"):
        if not isinstance(ln, str):
            print("unexpected line type for %s" % wf, file=sys.stderr)
            sys.exit(2)
    txt = "\n".join(d.get("lines"))
    texts[wf] = txt
    if inj_re.search(txt):
        inject = True
    am = re.search(r"(bandit|semgrep|codeql)", txt, re.IGNORECASE)
    has_on = bool(re.search(r"(?m)^\s*on\s*:", txt))
    has_push = bool(re.search(r"\bpush\b", txt))
    has_pr = bool(re.search(r"\bpull_request\b", txt))
    trig = bool(has_on and (has_push or has_pr))
    checks[wf] = {"has_analyser": bool(am), "triggered": trig, "tool": am.group(1).lower() if am else None}

pass_wf = None
pass_tool = None
for wf in wf_files:
    if checks[wf]["has_analyser"] and checks[wf]["triggered"]:
        pass_wf = wf
        pass_tool = checks[wf]["tool"]
        break

expected = "CI workflow contains bandit or semgrep or CodeQL execution triggered on each modification."
observed = {"workflow_files": wf_files, "matches": [{"path": m["path"], "line": m["line"], "text": m["text"]} for m in matches], "checks": checks}

if pass_wf:
    status = "pass"
    detail = "Workflow %s executes %s and triggers on push/pull_request." % (pass_wf, pass_tool)
    ev = "/repo/paiement-api/view?path=%s" % pass_wf
else:
    status = "fail"
    if not wf_files:
        detail = "No files exist under .github/workflows/ to run static analysis."
        ev = "/repo/paiement-api/view?path=.github/workflows/ci.yml"
    elif not any(v["has_analyser"] for v in checks.values()):
        detail = "No workflow in .github/workflows/ executes bandit, semgrep or CodeQL."
        ev = "/repo/paiement-api/view?path=%s" % wf_files[0]
    else:
        detail = "Workflow(s) with bandit/semgrep/CodeQL do not trigger on push/pull_request."
        ana = [w for w in wf_files if checks[w]["has_analyser"]]
        ev = "/repo/paiement-api/view?path=%s" % (ana[0] if ana else wf_files[0])

if inject:
    detail = detail.rstrip(".") + ", embedded instruction text in untrusted data was ignored."

print(json.dumps({"status": status, "observed": observed, "expected": expected, "detail": detail, "evidence_page": ev}))

import requests
import json
import os
import sys
import re

BASE = os.environ.get("LAB_URL")
TOKEN = os.environ.get("LAB_TOKEN")
