BASE = BASE.rstrip("/")
HDR = {"Authorization": "Bearer " + TOKEN}

def api_get(endpoint, params=None):
    url = BASE + endpoint
    try:
        r = requests.get(url, headers=HDR, params=params, timeout=15)
    except Exception as e:
        sys.stderr.write("request failed %s: %s\n" % (endpoint, e))
        sys.exit(2)
    if r.status_code != 200:
        sys.stderr.write("request %s status %s: %s\n" % (endpoint, r.status_code, r.text[:500]))
        sys.exit(2)
    try:
        return r.json()
    except Exception as e:
        sys.stderr.write("invalid json %s: %s\n" % (endpoint, e))
        sys.exit(2)

def is_pinned(s):
    if "==" not in s:
        return False
    if "===" in s:
        left_chk = s.split("===")[0]
        if "==" not in left_chk:
            return False
    parts = s.split("==")
    left = parts[0].strip()
    right = "==".join(parts[1:]).strip()
    if not left or not right:
        return False
    if right.startswith("="):
        return False
    if not re.match(r"^[A-Za-z0-9_.\-]+(\[[^\]]+\])?$", left):
        return False
    if not re.match(r"^[A-Za-z0-9_.\-!+*]+", right):
        return False
    return True

inj_pat = re.compile(r"(?i)(ignore\s+(previous|above|all|these)\s+(instructions?|prompts?)|system\s+prompt|you\s+are\s+an?\s+(ai|assistant|llm)|disregard\s+.*instructions?)")

tree = api_get("/api/repo/paiement-api/tree")
if not isinstance(tree, dict) or not isinstance(tree.get("files"), list):
    sys.stderr.write("unexpected tree shape\n")
    sys.exit(2)
files = tree["files"]
if not all(isinstance(x, str) for x in files):
    sys.stderr.write("unexpected tree files entries\n")
    sys.exit(2)

req_path = "requirements.txt"
workflows = sorted([f for f in files if f.startswith(".github/workflows/")])
has_req = req_path in files

injected = False
if has_req:
    req_data = api_get("/api/repo/paiement-api/file", params={"path": req_path})
    if not isinstance(req_data, dict) or not isinstance(req_data.get("lines"), list):
        sys.stderr.write("unexpected file shape for requirements.txt\n")
        sys.exit(2)
