import requests
import json
import os
import sys
import re

def fail_tech(msg):
    print("technical error: " + str(msg), file=sys.stderr)
    sys.exit(2)

try:
    BASE = os.environ["LAB_URL"]
except KeyError:
    fail_tech("missing LAB_URL")
try:
    TOKEN = os.environ["LAB_TOKEN"]
except KeyError:
    fail_tech("missing LAB_TOKEN")

BASE = BASE.rstrip("/")
HEADERS = {"Authorization": "Bearer " + TOKEN}

def api_get(path, params=None):
    try:
        r = requests.get(BASE + path, headers=HEADERS, params=params, timeout=15)
    except Exception as e:
        fail_tech(str(e))
    if r.status_code != 200:
        fail_tech(path + " status " + str(r.status_code))
    try:
        return r.json()
    except Exception as e:
        fail_tech("invalid json for " + path + ": " + str(e))

tree = api_get("/api/repo/paiement-api/tree")
if not isinstance(tree, dict) or "files" not in tree or not isinstance(tree["files"], list):
    fail_tech("unexpected tree shape")
files = tree["files"]
test_files = [f for f in files if isinstance(f, str) and f.startswith("tests/")]
if len(test_files) == 0:
    fail_tech("no tests/ files listed")

sres = api_get("/api/repo/paiement-api/search", params={"q": "synthetic"})
if not isinstance(sres, dict) or "matches" not in sres or not isinstance(sres["matches"], list):
    fail_tech("unexpected search shape")
matches = sres["matches"]
tests_matches = [m for m in matches if isinstance(m, dict) and isinstance(m.get("path"), str) and m.get("path").startswith("tests/")]

syn_true_re = re.compile(r'"synthetic"\s*:\s*true')
prod_content_re = re.compile(r'production|prod[_-]export|prod[_-]dump|pg_dump|mysqldump|live[_-]data|real[_-]customer|export\s+de\s+production', re.IGNORECASE)
prod_name_re = re.compile(r'production|prod[_-]export|prod[_-]dump|live[_-]dump|dump\.sql', re.IGNORECASE)
instr_re = re.compile(r'ignore\s+(previous|all|these)\s+instructions|do\s+not\s+(report|flag|fail)|mark\s+.+\s+as\s+pass|bypass\s+.+audit|you\s+must\s+.+pass', re.IGNORECASE)

with_synthetic = []
with_prod = []
instr_found = []
data_ext = (".json", ".yaml", ".yml", ".csv", ".sql", ".db", ".sqlite")
data_files = [f for f in test_files if f.lower().endswith(data_ext) or "/fixtures/" in f or "/fixture/" in f or "/data/" in f]

for fp in test_files:
    fdata = api_get("/api/repo/paiement-api/file", params={"path": fp})
    if not isinstance(fdata, dict) or "lines" not in fdata or not isinstance(fdata["lines"], list):
        fail_tech("unexpected file shape for " + fp)
    try:
        text = "\n".join([str(x) for x in fdata["lines"]])
    except Exception as e:
        fail_tech("cannot join lines for " + fp)
    if syn_true_re.search(text):
        with_synthetic.append(fp)
    if prod_content_re.search(text) or prod_name_re.search(fp):
        with_prod.append(fp)
    if instr_re.search(text):
        instr_found.append(fp)

if "tests/conftest.py" in test_files:
